fn main() {     if std::env::var("CARGO_CFG_TARGET_OS").unwrap_or_default() == "windows" {         let mut res = winres::WindowsResource::new();         res.set_icon("assets/icons/icon.ico");         if let Err(e) = res.compile() {             eprintln!("Warning: Failed to compile Windows resources: {}", e);         }     }     slint_build::compile("ui/main_window.slint").unwrap();     println!("cargo:rerun-if-changed=ui/main_window.slint");     println!("cargo:rerun-if-changed=build.rs");     println!("cargo:rerun-if-changed=assets/icons/icon.ico"); }